function staleSession(){const e=Error("Session changed; old response discarded");e.staleSession=true;return e;}
async function request(path,options={}){
 const authToken=token,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),options.method==="POST"?120000:15000);
 const multipart=options.body instanceof FormData;
 const headers={Authorization:`Bearer ${authToken}`,...(!multipart?{"Content-Type":"application/json"}:{}),...options.headers};
 try{
  const response=await fetch(path,{...options,headers,signal:controller.signal});
  if(authToken!==token)throw staleSession();
  if(response.status===401){const signingIn=path==="/v1/sign-in";logout();byId("login-title").textContent=signingIn?"Sign in":"Session expired";byId("session-message").hidden=false;byId("session-message").textContent=signingIn?"Access token not recognized. Check the token issued for your account.":"Sign in again to continue.";const e=Error(signingIn?"Access token not recognized. Check your saved token.":FinTrustDisplay.failure(401,view));e.sessionExpired=true;e.body={};throw e;}
  let body;try{body=await response.json();}catch{throw Error("Unexpected server response");}
  if(authToken!==token)throw staleSession();
  if(!response.ok){const failure=Error(FinTrustDisplay.failure(response.status,view));failure.body=body;failure.httpStatus=response.status;throw failure;}
  return body;
 }catch(e){if(authToken!==token&&!e.sessionExpired)throw staleSession();throw e;}finally{clearTimeout(timeout);}
}
