 charts.append(overviewChart("Transaction activity",data.daily_transactions.map(r=>({label:r.day,count:r.transactions})),true),overviewChart("Risk distribution",data.risk_distribution.map(r=>({label:r.risk_level,count:r.count}))));
 const scenarios=node("section",""),outcomes=node("section","");scenarios.className=outcomes.className="workbench-chart";
