function navigate(page){view=page;offset=0;batchSelection=null;byId("filter-status").value="";load();}
function showRejected(rows){const rejected=rows.filter(r=>r.action==="UPLOAD_REJECTED");const panel=node("section","");panel.append(node("p","Rejected before row processing. These events do not create accepted batches or financial entries."));panel.append(table(rejected.map(r=>({...r,reason:rejectionReason(r.reason_code)})),["filename","actor","attempted_at","reason_code","reason","rows_processed"]));byId("content").replaceChildren(panel);}
function rejectionReason(code){return {EMPTY_FILE:"Empty file. Add transaction rows.",HEADER_ONLY_FILE:"No transaction rows. Add rows below the headers.",UNSUPPORTED_FILE_TYPE:"Upload a transaction CSV file.",INVALID_CSV_SCHEMA:"Check required headers for missing, duplicate or unsupported columns.",INVALID_FILE_FORMAT:"Invalid CSV format. Check the file before uploading again.",UNSUPPORTED_ENCODING:"Save the CSV as UTF-8.",FILE_TOO_LARGE:"File exceeds 1 MiB. Split it into smaller files."}[code]||"File rejected. Correct it and upload again.";}
function showNotifications(){const panel=node("section","");panel.append(node("p","Session notifications · serious outcomes remain visible until acknowledged. Upload and rejection receipts are retained in intake history."));for(const item of [...notices].sort((a,b)=>Number(a.acknowledged)-Number(b.acknowledged))){const row=node("article","");row.className="notification "+item.severity.toLowerCase();row.append(node("strong",item.title+(item.acknowledged?" · Acknowledged":"")),node("p",item.message),node("p",item.action),node("small",item.time));if(item.page)row.append(button("Open "+item.page,()=>item.object&&item.page==="Ingestion Batches"?openBatch(item.object):navigate(item.page)));if(!item.acknowledged)row.append(button("Acknowledge notice",()=>{item.acknowledged=true;showNotifications();}));panel.append(row);}if(!notices.length)panel.append(node("p","No new notifications."));byId("content").replaceChildren(panel);}
function overviewChart(title,rows,line=false){const panel=title==="Risk distribution"?riskDistribution(rows):chart(title,rows,line);const values=panel.querySelector('.table-scroll');if(values){const detail=node("details","");detail.append(node("summary","View exact chart values"),values);panel.append(detail);}return panel;}
