function emptyMessage(page){return {"Review Queue":"No risk events currently need review.",Quarantine:"No rows currently need correction.","Rejected Uploads":"No rejected files for this period.",Notifications:"No new notifications.",Operations:"No technical failures require attention.",Transactions:"No accepted transactions in this scope.","Account History":"No transactions for this account.","Risk Events":"No flagged transactions in this scope.","Ingestion Batches":"No uploaded files in this scope."}[page]||"No records in this scope.";}
