function reviewFilters(meta){const tabs=node("div","");tabs.className="tabs";tabs.setAttribute("aria-label","Review ownership filters");for(const [label,value]of [["My reviews","mine"],["Unassigned","unassigned"],["All open","open"],["High risk","high"],["Over SLA","over_sla"]]){const b=button(label,()=>{reviewQueueFilter=value;offset=0;load();});b.setAttribute("aria-pressed",String(reviewQueueFilter===value));tabs.append(b);}byId("content").prepend(tabs);if(meta?.sla_configured===false)tabs.after(node("p","No review SLA is configured. No deadline has been assumed."));}
async function assignReview(row,assignee,notes="Claimed for investigation"){try{await request(`/v1/reviews/${row.risk_event_id}/assignment`,{method:"POST",body:JSON.stringify({request_id:crypto.randomUUID(),expected_version:row.version,assignee,notes})});notify("Review assignment saved.","SUCCESS","Review Queue");await load();}catch(e){error(e);}}
