let investigationGeneration=0,drawerReturnFocus=null;
function closeInvestigation(){investigationGeneration++;const panel=byId('investigation-drawer');if(panel?.contains(byId('action'))){byId('action').hidden=true;document.querySelector('main').insertBefore(byId('action'),byId('content'));}if(panel?.contains(byId("error")))document.querySelector("main").prepend(byId("error"));panel?.remove();if(drawerReturnFocus?.isConnected)drawerReturnFocus.focus();document.querySelectorAll("tr.is-selected").forEach(r=>r.classList.remove("is-selected"));}
function drawer(title){const opener=document.activeElement;closeInvestigation();drawerReturnFocus=opener;opener?.closest("tr")?.classList.add("is-selected");const panel=node('aside','');panel.id='investigation-drawer';panel.className='investigation-drawer';panel.setAttribute('role','region');panel.setAttribute('aria-label',title);panel.tabIndex=-1;const bar=node('div','');bar.className='drawer-bar';bar.append(node('h2',title),button('Close detail',closeInvestigation));panel.append(bar);document.querySelector('main').append(panel);panel.focus();return panel;}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeInvestigation();});
async function openInvestigation(row){const panel=drawer('Risk investigation');const own=investigationGeneration;panel.append(node('p','Loading evidence...'));try{const d=(await request(`/v1/risk-events/${row.risk_event_id}`)).data;if(own!==investigationGeneration||!principal)return;panel.lastChild.remove();
const composition=investigationLayout(panel,d);function section(title,content){const s=node('section','');s.dataset.evidenceGroup=['AUDIT TIMELINE','REVIEW HISTORY'].includes(title)?'history':title==='RELATED TRANSACTIONS'?'related':'risk';s.append(node('h3',title),content);if(title==='NEXT STEPS')composition.actions.prepend(s);else if(title==='ALERT AND REVIEW')composition.actions.append(s);else if(title==='WHY IS IT RISKY')composition.evidence.insertBefore(s,composition.evidence.querySelector('section').nextSibling);else composition.evidence.append(s);}
section('WHAT HAPPENED',investigationFacts({risk_event_id:d.risk_event_id,tx_id:d.tx_id,account_id:d.account_id,amount:d.amount,currency:d.currency,merchant:d.merchant,tx_type:d.tx_type}));
section('WHEN',investigationFacts({transaction_time:d.tx_date,created_at:d.created_at,last_updated:d.updated_at,age_seconds:d.age_seconds}));
section('WHERE',investigationFacts({account_id:d.account_id,source_system:d.source_system,source_reference:d.source_transaction_id,country:d.country,source_file:d.risk?.source?.key,source_row:d.risk?.source?.row,source_version:d.risk?.source?.version}));
const signals=node('div','');signals.append(investigationFacts({risk_level:d.risk_level,risk_score:d.risk_score,rule_version:d.risk?.rule_version}));for(const s of d.signals){signals.append(node('h4',s.rule),node('p',s.reason),investigationFacts({triggered_value:s.triggered_value??'Not captured in scoring evidence',threshold:s.threshold??'See rule explanation',context:s.context,created_at:s.created_at}));}signals.append(node('p',d.signal_evidence_note));section('WHY IS IT RISKY',signals);
section('ACCOUNT CONTEXT',investigationFacts(d.account_context));section('RELATED TRANSACTIONS',table(d.related_transactions,['tx_id','amount','currency','tx_date','risk_level','review_status'],(td,t)=>td.append(button('Investigate',()=>t.risk_event_id?openInvestigation(t):openTransaction(t.tx_id)))));if(d.related_truncated)panel.append(node('p','Showing the 20 most recent related transactions.'));
section('ALERT AND REVIEW',investigationFacts({alert_state:d.alert.delivery_state,alert_source:d.alert.source,reconciliation_required:d.alert.reconciliation_required,review_status:d.review_status,assignee_label:d.assignee_label}));
const next=node('div','');next.append(node('p','Review decisions do not freeze, reverse or delete transactions.'));
if(d.allowed_actions.claim)next.append(button('Claim Review',async()=>{await assignReview(d,principal.subject);openInvestigation(d);}));
if(d.allowed_actions.assign)next.append(button('Assign',()=>{const target=node('section','');composition.actions.append(target);assignmentEditor(d,target);}));
if(d.allowed_actions.note){const form=node('form','');const label=node('label','Investigation notes');const text=node('textarea','');text.required=true;text.maxLength=2000;label.append(text);form.append(label);const actions=node('select','');actions.setAttribute('aria-label','Investigation action');for(const [v,label] of [['NOTE','Add Note'],['CLEARED','Clear'],['CONFIRMED_RISK','Confirm Risk'],['ESCALATED','Escalate']]){const o=node('option',label);o.value=v;actions.append(o);}const outcomes=node('div','');outcomes.className='outcome-actions';for(const option of actions.options){const b=button(option.textContent,()=>{actions.value=option.value;for(const item of outcomes.children)item.setAttribute('aria-pressed',String(item===b));text.focus();});b.setAttribute('aria-pressed',String(option.value==='NOTE'));outcomes.append(b);}actions.onchange=()=>{for(const [i,item]of [...outcomes.children].entries())item.setAttribute('aria-pressed',String(actions.options[i].value===actions.value));};form.append(outcomes,actions);const save=node('button','Save investigation');save.type='submit';form.append(save);let retry=null;form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{let body={expected_version:d.version,notes:text.value};let path=`/v1/reviews/${d.risk_event_id}/notes`;if(actions.value!=='NOTE'){body.status=actions.value;body.resolution_code={CLEARED:'VALID_ACTIVITY',CONFIRMED_RISK:'CONFIRMED_SUSPICIOUS',ESCALATED:'SPECIALIST_REVIEW'}[actions.value];path=`/v1/reviews/${d.risk_event_id}/transition`;}const signature=JSON.stringify(body);if(!retry||retry.signature!==signature)retry={signature,id:crypto.randomUUID()};await request(path,{method:'POST',body:JSON.stringify({...body,request_id:retry.id})});await load();await openInvestigation(d);}catch(e){error(e);}finally{save.disabled=false;}};next.append(form);}else if(!d.allowed_actions.claim&&!d.allowed_actions.assign)next.append(node('p','Read-only. Notes and decisions require assignment to an active Analyst.'));section('NEXT STEPS',next);
section('AUDIT TIMELINE',table(d.timeline,['event_type','occurred_at','actor_subject','actor_type']));section('REVIEW HISTORY',table(d.review_history,['version','before_status','after_status','actor_subject','notes','changed_at']));composition.evidence.append(node('p',d.timeline_complete?'Recorded timeline complete.':'Timeline is bounded or historical evidence is incomplete.'));}catch(e){if(own===investigationGeneration){panel.append(node('p','Investigation unavailable.'));error(e);}}}
function investigationFilters(meta){const rail=node('form','');rail.className='investigation-filters';rail.setAttribute('aria-label','Investigation filters');for(const [key,label,options] of [['risk_level','Severity',['','Low','Medium','High']],['scenario','Scenario',['','HIGH_AMOUNT','VERY_HIGH_AMOUNT','HIGH_VELOCITY','CROSS_BORDER','POSSIBLE_DUPLICATE_CHARGE','TRANSFER','MERCHANT_MARKER']],['sort','Sort',['oldest','newest','severity','amount']]]){const l=node('label',label),s=node('select','');s.name=key;s.setAttribute('aria-label',label);options.forEach(v=>{const o=node('option',v||'All');o.value=v;s.append(o);});s.value=investigationFiltersState[key]||'';l.append(s);rail.append(l);}const l=node('label','Assignee username'),input=node('input','');input.name='assignee';input.maxLength=200;input.value=investigationFiltersState.assignee||'';l.append(input);rail.append(l);const slaLabel=node('label','Over SLA'),sla=node('input','');sla.type='checkbox';sla.name='over_sla';sla.value='1';sla.checked=Boolean(investigationFiltersState.over_sla);slaLabel.append(sla);rail.append(slaLabel,node('button','Apply investigation filters'));rail.onsubmit=e=>{e.preventDefault();investigationFiltersState=Object.fromEntries(new FormData(rail));offset=0;load();};const count=node('p',`${meta?.total_count??0} matching events | ${meta?.high_count??0} HIGH | ${meta?.active_count??0} active reviews`);count.className='quick-counts';const root=byId('content'),facets=node('aside',''),results=node('div','');facets.className='filter-rail';facets.append(node('h3','FILTER EVENTS'),rail,secondaryButton('Reset filters',()=>{investigationFiltersState={sort:'oldest'};offset=0;load();}));results.className='explorer-results';results.append(...root.childNodes);results.prepend(count);root.classList.add('explorer-grid');root.replaceChildren(facets,results);if(investigationFiltersState.over_sla)results.prepend(node('p',meta?.sla_configured===false?'Review SLA not configured. No deadline has been assumed.':'Over SLA includes active reviews only.'));}
let investigationFiltersState={sort:'oldest'};

function wireQueueRow(tr,row){
 const first=tr.querySelector('button');if(!first||(!row.risk_event_id&&!row.quarantine_id))return;
 tr.classList.add('investigable-row');
 tr.dataset.severity=String(row.risk?.risk_level||row.risk_level||'').toLowerCase();
 tr.onclick=e=>{if(!e.target.closest('button,a,input,select,textarea')){first.focus();first.click();}};

}

byId("apply-insights-filters").onclick=()=>{offset=0;load();};

function riskScore(raw){
 const box=node("span","");box.className="risk-score";
 const score=raw===null||raw===undefined||raw===""?null:Number(raw);
 if(score===null||!Number.isFinite(score)||score<0||score>100){box.classList.add("unassessed");box.textContent="Not assessed";box.title="No recorded risk assessment. This is not a zero score.";return box;}
 box.append(node("strong",String(score)),node("small","/100"));
 const track=node("span","");track.className="score-track";track.setAttribute("aria-hidden","true");const bar=node("span","");bar.style.width=score+"%";track.append(bar);box.append(track);
 box.title="Recorded rule score, not a probability of fraud.";return box;
}
function riskDistribution(rows){
 const panel=node("section","");panel.className="insight-chart risk-distribution";heading(panel,"Risk distribution");
 const total=rows.reduce((n,r)=>n+Number(r.count),0);if(!total){panel.append(node("p","No assessed transactions in this scope."));return panel;}
 const layout=node("div","");layout.className="distribution-layout";
 const ns="http://www.w3.org/2000/svg",svg=document.createElementNS(ns,"svg");svg.setAttribute("viewBox","0 0 180 180");svg.setAttribute("role","img");svg.setAttribute("aria-label",`Risk distribution: ${total} assessed transactions. Exact counts follow.`);
 const add=(tag,attrs,text)=>{const el=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,String(v)));if(text!==undefined)el.textContent=text;svg.append(el);return el;};
 add("circle",{cx:90,cy:90,r:65,fill:"none",stroke:"#edf1f5","stroke-width":18});let offset=0;const circumference=2*Math.PI*65;
 const colors={Low:"#16816b",Medium:"#d49a25",High:"#c84345"},legend=node("div","");legend.className="distribution-legend";
 for(const r of rows){const length=Number(r.count)/total*circumference;add("circle",{cx:90,cy:90,r:65,fill:"none",stroke:colors[r.label]||"#718293","stroke-width":18,"stroke-dasharray":`${length} ${circumference-length}`,"stroke-dashoffset":-offset,transform:"rotate(-90 90 90)"});offset+=length;const item=node("p","");const dot=node("span","");dot.className="legend-dot";dot.style.background=colors[r.label]||"#718293";item.append(dot,node("span",r.label),node("strong",String(r.count)));legend.append(item);}
 add("text",{x:90,y:91,"text-anchor":"middle","font-size":30,"font-weight":700,fill:"#1b3444"},total);add("text",{x:90,y:112,"text-anchor":"middle","font-size":12,fill:"#647584"},"assessed");layout.append(svg,legend);panel.append(layout,table(rows,["label","count"]));return panel;
}
